/* Generated by build_dashboards.py from REVIEW_JS. Edit there. */
(function(){
  var qEl=document.getElementById('rv-queue'), aEl=document.getElementById('rv-absent');
  if(!qEl) return;
  var m=document.createElement('meta'); m.name='robots'; m.content='noindex,nofollow'; document.head.appendChild(m);
  function esc(s){return String(s==null?'':s).replace(/[&<>]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c];});}
  function act(u,c,action,extra){
    return FC.sb.functions.invoke('review_award',{body:Object.assign({user_id:u,course_id:c,action:action},extra||{})})
      .then(function(r){ if(r&&r.error){alert('Failed: '+(r.error.message||'error'));} load(); });
  }
  function card(s,flags){
    var fl=(flags||[]).filter(function(f){return f.user_id===s.user_id&&f.course_id===s.course_id;});
    var mins=Math.round((s.snapshot_independent_seconds||0)/60);
    var cps=s.snapshot_checkpoints||{}; var cpN=Object.keys(cps).length; var cpTxt=cpN?(cpN+' complete'):'none';
    var id=s.user_id+'::'+s.course_id;
    return '<div class="card" style="padding:18px;margin-bottom:14px" data-id="'+esc(id)+'">'
      +(fl.length?'<p class="fine" style="color:var(--error)">FLAGGED: '+esc(fl[0].reason)+' &middot; clearing required</p>':'')
      +'<p class="small"><b>'+esc(s.user_id).slice(0,8)+'&hellip;</b> &middot; independent time '+mins+' min &middot; checkpoints '+cpTxt+' &middot; final answers '+esc(s.snapshot_final_answers_count)+'</p>'
      +'<div class="row wrap" style="gap:8px;align-items:center;margin:6px 0 8px"><span class="fine">NAME ON THE CERTIFICATE</span><input class="input" style="flex:1;min-width:180px" data-f="name" value="'+esc(s.recipient_display||'')+'" placeholder="Confirm the man\'s name"></div>'
      +'<div class="row wrap" style="gap:8px;margin-top:10px;align-items:center">'
      +'<input class="input" type="number" step="0.5" min="0" placeholder="Contact hours" style="width:130px" data-f="hours">'
      +'<select class="input" style="width:190px" data-f="att"><option value="facilitator">Attested by facilitator</option><option value="id">Confirmed by ID</option></select>'
      +'<input class="input" placeholder="Note (for return)" style="flex:1;min-width:140px" data-f="note">'
      +(fl.length?'<label class="fine"><input type="checkbox" data-f="clear"> Integrity cleared</label>':'')
      +'<button class="btn btn-primary btn-sm" data-a="approve">Approve</button>'
      +'<button class="btn btn-secondary btn-sm" data-a="return">Return</button>'
      +'<button class="btn btn-secondary btn-sm" data-a="sign">Sign</button>'
      +'</div></div>';
  }
  function load(){
    FC.ready.then(function(){
      if(!(FC.uid&&FC.uid())){ location.href='login.html?next=review.html'; return; }
      FC.sb.functions.invoke('review_award',{body:{action:'queue'}}).then(function(r){
        var d=r&&r.data&&r.data.data; var err=r&&r.error;
        if(err||!d){ qEl.innerHTML='<p class="fine">'+esc((err&&err.message)||'Reviewer role required, or the review function is not deployed yet.')+'</p>'; aEl.innerHTML=''; return; }
        qEl.innerHTML=(d.submitted&&d.submitted.length)?d.submitted.map(function(s){return card(s,d.flags);}).join(''):'<p class="fine">Nothing waiting. Good.</p>';
        aEl.innerHTML=(d.absent&&d.absent.length)?d.absent.map(function(e){var who=e.email?('<a href="mailto:'+esc(e.email)+'">'+esc(e.email)+'</a>'):(esc(e.user_id).slice(0,8)+'&hellip;');return '<p class="small">'+who+' &middot; last activity '+esc(e.last_activity_at||'never')+'</p>';}).join(''):'<p class="fine">Every enrolled man has been active inside 72 hours.</p>';
        qEl.querySelectorAll('[data-a]').forEach(function(b){ b.addEventListener('click',function(){
          var host=b.closest('[data-id]'); var parts=host.getAttribute('data-id').split('::');
          var extra={};
          if(b.getAttribute('data-a')==='approve'){
            extra.contact_hours=parseFloat(host.querySelector('[data-f=hours]').value||'0');
            extra.recipient_display=(host.querySelector('[data-f=name]').value||'').trim();
            if(!extra.recipient_display){ alert('Confirm the man\'s name before approving; it is what the certificate will carry.'); return; }
            extra.attestation_method=host.querySelector('[data-f=att]').value;
            var cl=host.querySelector('[data-f=clear]'); if(cl&&cl.checked) extra.integrity_cleared=true;
          }
          if(b.getAttribute('data-a')==='return'){ extra.note=host.querySelector('[data-f=note]').value; }
          act(parts[0],parts[1],b.getAttribute('data-a'),extra);
        });});
      });
    });
  }
  load();
})();
